"""🎮 Real 3D games from a short brief. A model picks the mode, the mood and the real things in it. This file holds the craft: controls for keys and touch, spawning, scoring, lives, sound, the film finish, and a bot that plays behind the menu so a preview is alive. Works with no model at all, and with plain shapes when a model file does not load."""
import html as _html
import json

MODES = {'runner': 'endless three lane run: dodge, jump and collect', 'arena': 'open ground: collect everything while hazards chase you'}
ROLES = ('player', 'hazard', 'pickup', 'scenery')

_CSS = """
html,body{margin:0;height:100%;overflow:hidden;background:var(--bg);color:#fff;font-family:system-ui,-apple-system,Segoe UI,sans-serif;touch-action:none;user-select:none}
canvas{position:fixed;inset:0;display:block}
#grade{position:fixed;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 42%,transparent 42%,rgba(0,0,0,var(--vig)) 100%)}
#hud{position:fixed;top:0;left:0;right:0;display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:16px 20px;pointer-events:none;opacity:0;transition:opacity .25s ease;text-shadow:0 2px 14px #000c}
#hud.on{opacity:1}
#hud b{display:block;font:800 clamp(30px,5vw,58px)/1 var(--head),system-ui;letter-spacing:-.01em;font-variant-numeric:tabular-nums}
#hud small{display:block;font:700 11px/1.4 ui-monospace,Menlo,monospace;letter-spacing:.14em;opacity:.8}
#hud .r{text-align:right}
#lives{display:flex;gap:6px;margin-top:8px}#lives i{width:14px;height:14px;border-radius:50%;background:var(--tint);box-shadow:0 0 12px var(--tint);transition:transform .2s ease,opacity .2s ease}#lives i.off{opacity:.18;transform:scale(.6);box-shadow:none}
#pace{width:min(180px,34vw);height:5px;margin-top:8px;border-radius:9px;background:#ffffff26;overflow:hidden}#pace i{display:block;height:100%;width:100%;background:var(--tint);transform-origin:left;transform:scaleX(0)}
#over{position:fixed;inset:0;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-end;padding:7vh 6vw;box-sizing:border-box;background:linear-gradient(to top,#000b,transparent 62%);transition:opacity .3s ease}
#over.off{opacity:0;pointer-events:none}
h1{margin:0;font:800 clamp(44px,9vw,120px)/.95 var(--head),system-ui;letter-spacing:-.02em;text-shadow:0 4px 40px #000a}
#sub{max-width:620px;margin:10px 0 0;font-size:clamp(15px,2vw,21px);opacity:.9;text-shadow:0 2px 16px #000a}
#keys{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0 0}#keys span{padding:6px 10px;border:1px solid #ffffff40;border-radius:8px;background:#0006;font:700 12px ui-monospace,Menlo,monospace;letter-spacing:.06em}
#result{margin:12px 0 0;font:800 clamp(20px,3vw,30px) var(--head),system-ui;color:var(--tint);min-height:1.2em}
.btn{min-height:48px;margin-top:14px;padding:13px 30px;border:0;border-radius:999px;background:#fff;color:#000;font:800 17px system-ui;cursor:pointer;transition:transform .15s ease,box-shadow .15s ease}
.btn:hover{transform:translateY(-2px);box-shadow:0 8px 30px var(--tint)}.btn:active{transform:scale(.97)}.btn:focus-visible{outline:3px solid #fff;outline-offset:3px}.btn:disabled{opacity:.6;cursor:wait}
#mute{position:fixed;right:14px;bottom:30px;width:40px;height:40px;border-radius:50%;border:1px solid #ffffff40;background:#0006;color:#fff;font:700 11px system-ui;cursor:pointer}#mute:hover{background:#000a}#mute:focus-visible{outline:2px solid #fff}
#none{position:fixed;inset:0;display:none;place-items:center;background:#000;z-index:9}
.credit{position:fixed;right:10px;bottom:8px;font-size:10px;opacity:.6;max-width:70vw;text-align:right}
@media (prefers-reduced-motion: reduce){#hud,#over,.btn,#lives i{transition:none}}
"""

